// setGenerationAnnotationOnVmi sets the VirtualMachineGenerationAnnotation on the
// vmi with the given generation formatted as a decimal string. The annotation is
// merged into any existing annotations, and the annotations map is initialized if
// it is nil.
func setGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) {
	annotations := vmi.GetAnnotations()
	if annotations == nil {
		annotations = make(map[string]string)
	}

	annotations[virtv1.VirtualMachineGenerationAnnotation] = strconv.FormatInt(generation, 10)
	vmi.SetAnnotations(annotations)
}

// getGenerationAnnotation returns a pointer to the string value of the
// VirtualMachineGenerationAnnotation on the vmi if it exists. If the annotation
// does not exist (or the annotations map is empty), nil is returned with a nil
// error.
func getGenerationAnnotation(vmi *virtv1.VirtualMachineInstance) (i *string, err error) {
	if vmi == nil {
		return nil, errors.New("received nil pointer for vmi")
	}

	currentGenerationAnnotation, found := vmi.Annotations[virtv1.VirtualMachineGenerationAnnotation]
	if found {
		return &currentGenerationAnnotation, nil
	}

	return nil, nil
}

// getGenerationAnnotationAsInt is a helper to get the generation annotation on the
// vmi as an *int64. If the annotation does not exist, or the annotation value is
// malformed (not an integer), nil is returned with a nil error, since a malformed
// annotation is treated as if it does not exist.
func getGenerationAnnotationAsInt(vmi *virtv1.VirtualMachineInstance, logger *log.FilteredLogger) (i *int64, err error) {
	currentGeneration, err := getGenerationAnnotation(vmi)
	if err != nil {
		return nil, err
	}
	if currentGeneration == nil {
		return nil, nil
	}

	generation, err := strconv.ParseInt(*currentGeneration, 10, 64)
	if err != nil {
		// A malformed annotation is treated as if the annotation does not
		// exist, so that it can be re-synced from the controller revision.
		if logger != nil {
			logger.Reason(err).Errorf("Failed to parse generation annotation %s as an int from vmi %s", *currentGeneration, vmi.Name)
		}
		return nil, nil
	}

	return &generation, nil
}

// patchVmGenerationAnnotationOnVmi patches the vmi resource in the Kubernetes API
// to set the VirtualMachineGenerationAnnotation to the given generation formatted
// as a decimal string. It returns the patched vmi.
func (c *Controller) patchVmGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	oldAnnotations := vmi.Annotations

	newVmi := vmi.DeepCopy()
	setGenerationAnnotationOnVmi(generation, newVmi)

	patchSet := patch.New()
	if oldAnnotations == nil {
		patchSet.AddOption(patch.WithAdd("/metadata/annotations", newVmi.Annotations))
	} else {
		patchSet.AddOption(
			patch.WithTest("/metadata/annotations", oldAnnotations),
			patch.WithReplace("/metadata/annotations", newVmi.Annotations),
		)
	}

	patchBytes, err := patchSet.GeneratePayload()
	if err != nil {
		return vmi, err
	}

	updatedVmi, err := c.clientset.VirtualMachineInstance(vmi.Namespace).Patch(context.Background(), vmi.Name, types.JSONPatchType, patchBytes, metav1.PatchOptions{})
	if err != nil {
		return vmi, err
	}

	return updatedVmi, nil
}

// patchVmGenerationFromControllerRevision patches the vmi generation annotation
// with the generation stored in the vmi's corresponding controller revision. It
// returns the patched vmi and the generation value from the revision.
func (c *Controller) patchVmGenerationFromControllerRevision(vmi *virtv1.VirtualMachineInstance, logger *log.FilteredLogger) (*virtv1.VirtualMachineInstance, *int64, error) {
	currentRevision, err := c.getControllerRevision(vmi.Namespace, vmi.Status.VirtualMachineRevisionName)
	if currentRevision == nil || err != nil {
		return vmi, nil, err
	}

	generation := currentRevision.Revision
	vmi, err = c.patchVmGenerationAnnotationOnVmi(generation, vmi)
	if err != nil {
		return vmi, &generation, err
	}

	return vmi, &generation, nil
}

// conditionallyBumpGenerationAnnotationOnVmi bumps the vmi generation annotation
// to vm.Generation, but only when the generation differs from the current
// annotation value AND the VM's current template spec is identical to the template
// spec stored in the controller revision. Changes to non-template fields (such as
// the run strategy) therefore do not prevent a bump. If the annotation is missing,
// it proceeds as if a bump is needed. The (possibly patched) vmi is returned.
func (c *Controller) conditionallyBumpGenerationAnnotationOnVmi(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	if vmi == nil || vm == nil {
		return vmi, nil
	}

	currentGeneration, err := getGenerationAnnotation(vmi)
	if err != nil {
		return vmi, err
	}
	if currentGeneration != nil && *currentGeneration == strconv.FormatInt(vm.Generation, 10) {
		return vmi, nil
	}

	currentRevision, err := c.getControllerRevision(vmi.Namespace, vmi.Status.VirtualMachineRevisionName)
	if currentRevision == nil || err != nil {
		return vmi, err
	}

	revisionSpec := &VirtualMachineRevisionData{}
	if err = json.Unmarshal(currentRevision.Data.Raw, revisionSpec); err != nil {
		return vmi, err
	}

	// Only bump the generation annotation if the template has not changed. If
	// the template has changed, a restart is required before the generation can
	// be considered observed.
	if equality.Semantic.DeepEqual(revisionSpec.Spec.Template, vm.Spec.Template) {
		vmi, err = c.patchVmGenerationAnnotationOnVmi(vm.Generation, vmi)
		if err != nil {
			return vmi, err
		}
	}

	return vmi, nil
}

